// SA'DA H2O — Supabase "Send SMS" Auth Hook
// ============================================================================
// Supabase Auth calls THIS endpoint whenever it needs to deliver an OTP by SMS.
// It replaces the built-in provider (Twilio etc.) so auth OTPs go out over the
// existing SA'DA relay → Taqnyat, exactly like every other SMS in this app.
//
// Configure at: Supabase Dashboard → Authentication → Hooks → Send SMS
//   Type: HTTPS
//   URL:  https://sada-water-booking.vercel.app/api/auth-sms-hook
//   Secret: generated by the dashboard, then set as SEND_SMS_HOOK_SECRET in Vercel
//
// WHY THIS IS SEPARATE FROM /api/send-sms:
//   1. Different auth. /api/send-sms trusts a shared X-Secret-Key from the
//      browser. This endpoint verifies a Standard Webhooks HMAC signature from
//      Supabase — a much stronger check, and the only thing standing between a
//      public URL and an attacker draining the Taqnyat balance.
//   2. Different throttle. /api/send-sms enforces 3-per-15-min per phone. Auth
//      OTPs must not be subject to that: Supabase Auth applies its own rate
//      limits, and stacking the two could lock a customer out of both.
//
//   The droplet call below is duplicated from send-sms.js on purpose. Factoring
//   it into a shared module would mean editing the working SMS path, which is
//   explicitly off-limits. Duplication is the safer trade here.
//   If the relay ever moves, BOTH files must change. That's the cost.
//
// Payload from Supabase (Send SMS Hook):
//   { "user": { "id": "...", "phone": "966550667403", ... },
//     "sms":  { "otp": "123456" } }
// Response: 200 with {} means "sent". Any non-2xx makes Supabase fail the login.
// ============================================================================

const crypto = require('crypto');

const RELAY_HOST = 'relay.sadawater.com';
const RELAY_PATH = '/';
const RELAY_TIMEOUT_MS = 30_000;

const PHONE_RE = /^9665\d{8}$/;
const TIMESTAMP_TOLERANCE_S = 5 * 60;   // replay window

// Vercel must NOT parse the body: the HMAC is computed over the exact bytes
// Supabase sent. Re-serialising parsed JSON changes key order/whitespace and
// the signature would never match.
module.exports.config = { api: { bodyParser: false } };

function readRawBody(req) {
  return new Promise((resolve, reject) => {
    if (typeof req.body === 'string') return resolve(req.body);
    if (Buffer.isBuffer(req.body)) return resolve(req.body.toString('utf8'));
    let data = '';
    req.on('data', c => (data += c));
    req.on('end', () => resolve(data));
    req.on('error', reject);
  });
}

/**
 * Standard Webhooks signature check.
 * signed content = `${webhook-id}.${webhook-timestamp}.${raw body}`
 * expected       = base64( HMAC-SHA256( base64decode(secret), signedContent ) )
 * The header may carry several space-separated `v1,<sig>` pairs during rotation.
 */
function verifySignature(raw, headers, secretRaw) {
  const id = headers['webhook-id'];
  const ts = headers['webhook-timestamp'];
  const sigHeader = headers['webhook-signature'];
  if (!id || !ts || !sigHeader) return { ok: false, why: 'missing webhook headers' };

  const age = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
  if (!Number.isFinite(age) || age > TIMESTAMP_TOLERANCE_S) {
    return { ok: false, why: `timestamp outside tolerance (${age}s)` };
  }

  // Dashboard gives the secret as "v1,whsec_<base64>". Accept it with or
  // without that prefix so a copy-paste slip doesn't silently break logins.
  let secret = String(secretRaw).trim();
  if (secret.startsWith('v1,')) secret = secret.slice(3);
  if (secret.startsWith('whsec_')) secret = secret.slice(6);

  let key;
  try { key = Buffer.from(secret, 'base64'); }
  catch { return { ok: false, why: 'secret is not valid base64' }; }

  const expected = crypto.createHmac('sha256', key)
    .update(`${id}.${ts}.${raw}`).digest('base64');

  const provided = String(sigHeader).split(' ')
    .map(p => p.split(',')[1])
    .filter(Boolean);

  const expBuf = Buffer.from(expected);
  const match = provided.some(p => {
    const pBuf = Buffer.from(p);
    return pBuf.length === expBuf.length && crypto.timingSafeEqual(pBuf, expBuf);
  });
  return match ? { ok: true } : { ok: false, why: 'signature mismatch' };
}

// Duplicated from send-sms.js — see the note at the top of this file.
async function forwardToDroplet(to, body) {
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), RELAY_TIMEOUT_MS);
  try {
    const r = await fetch(`https://${RELAY_HOST}${RELAY_PATH}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ to, body }),
      signal: ac.signal
    });
    const text = await r.text();
    try { return JSON.parse(text); } catch { return { raw: text }; }
  } catch (err) {
    if (err.name === 'AbortError') throw new Error('Relay timeout');
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

module.exports = async function handler(req, res) {
  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });

  const secret = process.env.SEND_SMS_HOOK_SECRET;
  if (!secret) {
    // Fail CLOSED. Without the secret we cannot tell Supabase apart from an
    // attacker, and this endpoint spends real money on every call.
    console.error('auth-sms-hook: SEND_SMS_HOOK_SECRET is not set');
    return res.status(500).json({ error: { http_code: 500, message: 'Hook not configured' } });
  }

  let raw;
  try { raw = await readRawBody(req); }
  catch { return res.status(400).json({ error: { http_code: 400, message: 'Could not read body' } }); }

  const v = verifySignature(raw, req.headers, secret);
  if (!v.ok) {
    console.error('auth-sms-hook: rejected —', v.why);
    return res.status(401).json({ error: { http_code: 401, message: 'Invalid signature' } });
  }

  let event;
  try { event = JSON.parse(raw); }
  catch { return res.status(400).json({ error: { http_code: 400, message: 'Body is not JSON' } }); }

  const rawPhone = event?.user?.phone || '';
  const otp = event?.sms?.otp || '';
  const phone = String(rawPhone).replace(/[^\d]/g, '');

  if (!PHONE_RE.test(phone)) {
    // Business-rule error: tell Supabase, don't retry. Never echo the OTP.
    console.error('auth-sms-hook: bad phone shape');
    return res.status(400).json({ error: { http_code: 400, message: 'Only Saudi mobile numbers are supported.' } });
  }
  if (!/^\d{4,10}$/.test(otp)) {
    console.error('auth-sms-hook: missing or malformed otp');
    return res.status(400).json({ error: { http_code: 400, message: 'Malformed OTP in hook payload.' } });
  }

  const body = `SA'DA H2O: Your verification code is ${otp}. Do not share it with anyone.`;

  try {
    await forwardToDroplet(phone, body);
    // Supabase treats an empty 200 as success.
    return res.status(200).json({});
  } catch (err) {
    // Never log the OTP or the full number.
    console.error('auth-sms-hook: relay failed —', err.message);
    return res.status(500).json({ error: { http_code: 500, message: 'Could not send the verification code. Please try again.' } });
  }
};
